INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5150, 'primary research', '/ˈpraɪmeri rɪˈsɜːrtʃ/', 'noun', '{"zh-TW":["一手研究；原始研究"],"en":["original data collected directly for a specific research purpose"]}', NULL, 'conduct primary research / primary research findings', '[{"en":"The team conducted primary research through surveys and interviews.","zh-TW":"團隊通過調查和訪談進行了一手研究。"},{"en":"Primary research provides more targeted data than secondary sources.","zh-TW":"一手研究比二手來源提供更有針對性的數據。"}]', '{"opposite":"secondary research"}', NULL, 5, 5150, NULL),
(5151, 'prime rate', '/praɪm reɪt/', 'noun', '{"zh-TW":["基準利率；優惠利率"],"en":["the interest rate that banks charge their most creditworthy customers"]}', NULL, 'change in prime rate / prime rate loan', '[{"en":"The loan was priced at prime rate plus 2%.","zh-TW":"貸款以基準利率加2%定價。"},{"en":"A rise in the prime rate increases borrowing costs across the economy.","zh-TW":"基準利率上升增加了整個經濟的借貸成本。"}]', NULL, NULL, 4, 5151, NULL),
(5152, 'principal', '/ˈprɪnsɪpəl/', 'adjective', '{"zh-TW":["主要的；首要的"],"en":["most important"]}', '{"root":{"text":"princip","meaning":"first (第一)"},"suffix":{"text":"-al","meaning":"...的"}}', 'principal reason / principal investor', '[{"en":"The principal reason for the delay was funding.","zh-TW":"延遲的主要原因是資金。"},{"en":"She is the principal investor in the company.","zh-TW":"她是公司的主要投資者。"}]', '{"adverb":"principally","noun":"principal"}', NULL, 3, 5152, NULL),
(5153, 'principal amount', '/ˈprɪnsɪpəl əˈmaʊnt/', 'noun', '{"zh-TW":["本金金額"],"en":["the original sum of money borrowed or invested, excluding interest"]}', NULL, 'repay the principal amount / reduce the principal amount', '[{"en":"Monthly payments first cover interest before reducing the principal amount.","zh-TW":"每月付款先支付利息，再減少本金金額。"},{"en":"The principal amount of the bond was 10 million dollars.","zh-TW":"債券的本金金額為1000萬美元。"}]', NULL, NULL, 5, 5153, NULL),
(5154, 'principle', '/ˈprɪnsɪpəl/', 'noun', '{"zh-TW":["原則；原理"],"en":["a fundamental truth or rule"]}', '{"root":{"text":"princip","meaning":"first (第一)"}}', 'in principle / basic principle / guiding principle', '[{"en":"In principle, we agree with the proposal.","zh-TW":"原則上我們同意提案。"},{"en":"The company operates on ethical principles.","zh-TW":"公司按道德原則運營。"}]', '{"adjective":"principled"}', NULL, 3, 5154, NULL),
(5155, 'print', 'prɪnt', 'verb', '{"zh-TW":["列印；印刷","印刷出版"],"en":["to produce on paper","to publish"]}', NULL, 'print a document/print copies', '[{"en":"Please print five copies of the agenda.","zh-TW":"請列印五份議程。"}]', '{"noun":"print, printer","adjective":"printed"}', NULL, 2, 5155, NULL),
(5156, 'printer', '/ˈprɪntər/', 'noun', '{"zh-TW":["印表機"],"en":["a device that produces text or images on paper"]}', NULL, 'laser printer / wireless printer', '[{"en":"The wireless printer allows printing from any device.","zh-TW":"無線印表機允許從任何設備列印。"},{"en":"Please replace the printer cartridge when the ink runs low.","zh-TW":"墨水不足時請更換印表機墨匣。"}]', NULL, NULL, 3, 5156, NULL),
(5157, 'prior', '/ˈpraɪər/', 'adjective', '{"zh-TW":["先前的；優先的"],"en":["existing or happening before"]}', '{"root":{"text":"pri","meaning":"before (之前)"}}', 'prior to / prior experience / prior approval', '[{"en":"Prior experience is required for this role.","zh-TW":"這職位需要先前經驗。"},{"en":"Prior to the merger, the company was smaller.","zh-TW":"合併前公司較小。"}]', '{"noun":"priority","verb":"prioritize"}', NULL, 2, 5157, 180),
(5158, 'prioritize', '/praɪˈɒrɪtaɪz/', 'verb', '{"zh-TW":["優先排序；區分輕重緩急"],"en":["to arrange tasks in order of importance or urgency"]}', NULL, 'prioritize tasks / prioritize resources / prioritize effectively', '[{"en":"She learned to prioritize high-impact tasks over routine work.","zh-TW":"她學會了將高影響力任務排在常規工作之前。"},{"en":"The team reprioritized the backlog based on customer feedback.","zh-TW":"團隊根據客戶反饋重新排列了待辦清單的優先順序。"}]', '{"noun":"priority","adjective":"prioritized"}', NULL, 4, 5158, 708),
(5159, 'priority', '/praɪˈɒrəti/', 'noun', '{"zh-TW":["優先事項"],"en":["something regarded as more important than others","something more important than others"]}', '{"root":{"text":"prior","meaning":"before/first (在前/首先)"},"suffix":{"text":"-ity","meaning":"state (狀態)"},"logic":"排在前面的事項，即「優先事項」。"}', 'top priority / give priority to / set priorities', '[{"en":"Safety is our top priority.","zh-TW":"安全是我們的首要之務。"},{"en":"You need to set your priorities.","zh-TW":"你需要排定優先順序。"},{"en":"Customer safety is our top priority.","zh-TW":"客戶安全是首要之務。"}]', '{"verb":"prioritize","adjective":"prior"}', NULL, 3, 5159, 420),
(5160, 'priority boarding', '/''praɪˈɒrɪti ˌbɔːrdɪŋ/', 'noun', '{"zh-TW":["優先登機"],"en":["the right to board an aircraft before other passengers, typically for premium passengers"]}', NULL, 'receive priority boarding / priority boarding lane / priority boarding benefit', '[{"en":"Business class passengers enjoy priority boarding before general passengers.","zh-TW":"商務艙乘客在一般旅客之前享有優先登機。"},{"en":"Priority boarding is one of the perks of the airline''s elite membership tier.","zh-TW":"優先登機是航空公司精英會員級別的福利之一。"}]', NULL, NULL, 5, 5160, NULL),
(5161, 'privacy', '/ˈpraɪvəsi/', 'noun', '{"zh-TW":["隱私"],"en":["the state of being free from public attention"]}', '{"root":{"text":"priv","meaning":"separate (分離)"},"suffix":{"text":"-acy","meaning":"狀態"}}', 'privacy policy / invasion of privacy / protect privacy', '[{"en":"We take customer privacy seriously.","zh-TW":"我們重視客戶隱私。"},{"en":"Read our privacy policy for more details.","zh-TW":"閱讀我們的隱私政策。"}]', '{"adjective":"private","adverb":"privately"}', NULL, 3, 5161, NULL),
(5162, 'private equity', '/ˈpraɪvɪt ˈekwɪti/', 'noun', '{"zh-TW":["私募股權"],"en":["investment in companies not listed on a public exchange"]}', NULL, 'private equity firm / private equity investment / private equity deal', '[{"en":"The private equity firm acquired a stake in the startup.","zh-TW":"私募股權公司收購了這家新創公司的股份。"},{"en":"Private equity investors typically seek returns over 5-7 years.","zh-TW":"私募股權投資者通常在5-7年內尋求回報。"}]', '{"abbreviation":"PE"}', NULL, 5, 5162, NULL),
(5163, 'private placement', '/ˈpraɪvɪt ˈpleɪsmənt/', 'noun', '{"zh-TW":["私募配售"],"en":["the sale of securities directly to selected investors without a public offering"]}', NULL, 'complete a private placement / private placement memorandum', '[{"en":"The company raised $10 million through a private placement to institutional investors.","zh-TW":"公司通過向機構投資者私募配售籌集了1000萬元。"},{"en":"A private placement avoids the costs and disclosure requirements of a public offering.","zh-TW":"私募配售避免了公開募股的成本和披露要求。"}]', NULL, NULL, 5, 5163, NULL),
(5164, 'privatization', '/ˌpraɪvɪtɪˈzeɪʃən/', 'noun', '{"zh-TW":["私有化"],"en":["the transfer of a government-owned entity to private ownership"]}', NULL, 'pursue privatization / privatization program', '[{"en":"The privatization of the utility company attracted foreign investors.","zh-TW":"公用事業公司的私有化吸引了外國投資者。"},{"en":"Privatization aims to improve efficiency by introducing market competition.","zh-TW":"私有化旨在通過引入市場競爭提高效率。"}]', '{"verb":"privatize","adjective":"privatized"}', NULL, 5, 5164, NULL),
(5165, 'privilege', '/ˈprɪvɪlɪdʒ/', 'noun', '{"zh-TW":["特權；榮幸"],"en":["a special right or advantage"]}', '{"root":{"text":"priv","meaning":"private (私人)"},"suffix":{"text":"-lege","meaning":"law (法律)"}}', 'executive privilege / it is a privilege to', '[{"en":"It''s a privilege to work with this team.","zh-TW":"與這團隊合作是榮幸。"},{"en":"Access to the lounge is a member privilege.","zh-TW":"進入貴賓室是會員特權。"}]', '{"adjective":"privileged"}', NULL, 3, 5165, NULL),
(5166, 'prix fixe', '/priː fɪks/', 'noun', '{"zh-TW":["固定價位套餐"],"en":["a meal of several courses at a fixed price"]}', NULL, 'prix fixe menu / prix fixe dinner', '[{"en":"The restaurant offers a prix fixe dinner on Saturdays.","zh-TW":"餐廳週六提供固定價位晚餐套餐。"},{"en":"The prix fixe menu includes three courses.","zh-TW":"固定價位套餐包含三道菜。"}]', NULL, NULL, 3, 5166, NULL),
(5167, 'pro bono', '/prəʊ ˈbɒnəʊ/', 'phrase', '{"zh-TW":["義務的；免費的（法律服務）"],"en":["professional work done for free, usually for the public good"]}', NULL, 'pro bono work / pro bono legal services / provide pro bono', '[{"en":"The law firm offers pro bono services to low-income clients.","zh-TW":"律師事務所向低收入客戶提供免費法律服務。"},{"en":"Pro bono legal work is a professional obligation in many bar associations.","zh-TW":"義務法律工作在許多律師公會中是職業義務。"}]', NULL, NULL, 3, 5167, NULL),
(5168, 'pro forma', '/proʊ ˈfɔːrmə/', 'adjective', '{"zh-TW":["備考的；假設的"],"en":["based on projected or hypothetical figures rather than actual results"]}', NULL, 'pro forma financial statements / pro forma earnings', '[{"en":"The pro forma accounts excluded one-off restructuring charges.","zh-TW":"備考帳目排除了一次性重組費用。"},{"en":"Investors should review both actual and pro forma earnings carefully.","zh-TW":"投資者應仔細審查實際和備考盈利。"}]', NULL, NULL, 3, 5168, NULL),
(5169, 'pro forma invoice', '/proʊ ˈfɔːrmə ˈɪnvɔɪs/', 'noun', '{"zh-TW":["形式發票；預計發票"],"en":["a preliminary invoice sent before goods are shipped, estimating costs"]}', NULL, 'issue a pro forma invoice / pro forma invoice details', '[{"en":"The buyer requested a pro forma invoice to arrange advance payment.","zh-TW":"買方請求了一份形式發票以安排預付款。"},{"en":"A pro forma invoice is not a demand for payment but a price estimate.","zh-TW":"形式發票不是付款要求，而是價格估算。"}]', NULL, NULL, 5, 5169, NULL),
(5170, 'pro rata', '/proʊ ˈrɑːtə/', 'adjective', '{"zh-TW":["按比例的；相稱的"],"en":["proportional to time or share of a total amount"]}', NULL, 'pro rata basis / pro rata payment', '[{"en":"The bonus was paid on a pro rata basis for partial-year employees.","zh-TW":"獎金按比例支付給部分年度員工。"},{"en":"Costs were allocated pro rata based on each division''s revenue.","zh-TW":"成本根據每個部門的收入按比例分配。"}]', NULL, NULL, 3, 5170, NULL),
(5171, 'pro-cyclical', '/prəʊ ˈsaɪklɪkəl/', 'adjective', '{"zh-TW":["順週期性的"],"en":["tending to amplify economic fluctuations rather than dampen them"]}', NULL, 'pro-cyclical behavior / pro-cyclical policy / pro-cyclical effect', '[{"en":"Banking regulations should avoid pro-cyclical effects.","zh-TW":"銀行法規應避免順週期性效應。"},{"en":"Pro-cyclical fiscal policy can deepen recessions by cutting spending.","zh-TW":"順週期性財政政策通過削減開支可能加深衰退。"}]', '{"noun":"pro-cyclicality"}', NULL, 4, 5171, NULL),
(5172, 'proactive', '/proʊˈæktɪv/', 'adjective', '{"zh-TW":["積極主動的；前瞻性的"],"en":["taking initiative to deal with issues before they arise"]}', NULL, 'proactive approach / proactive communication / proactive management', '[{"en":"A proactive approach to risk management prevents costly surprises.","zh-TW":"積極主動的風險管理方法防止了代價高昂的意外。"},{"en":"She was praised for her proactive communication with clients.","zh-TW":"她因與客戶的積極主動溝通而受到讚揚。"}]', '{"adverb":"proactively","antonym":"reactive"}', NULL, 3, 5172, 908),
(5173, 'proactive governance', '/prəʊˈæktɪv ˈɡʌvənəns/', 'noun', '{"zh-TW":["主動治理"],"en":["governance that anticipates and addresses problems before they arise"]}', NULL, 'practice proactive governance / proactive governance model / move toward proactive governance', '[{"en":"Proactive governance uses data and forecasting to prevent crises.","zh-TW":"主動治理使用數據和預測來防止危機。"},{"en":"Proactive governance of AI requires regulation before harms materialize.","zh-TW":"人工智慧的主動治理需要在危害出現之前進行監管。"}]', NULL, NULL, 5, 5173, NULL),
(5174, 'proactive risk management', '/''prəʊˌæktɪv ˈrɪsk ˌmænɪdʒmənt/', 'noun', '{"zh-TW":["主動風險管理；前瞻性風險管理"],"en":["an approach that anticipates potential risks and takes action before problems arise"]}', NULL, 'implement proactive risk management / benefit of proactive risk management', '[{"en":"Proactive risk management prevents crises rather than merely responding to them.","zh-TW":"主動風險管理是在危機發生前預防，而不僅僅是應對。"},{"en":"Companies with strong proactive risk management cultures experience fewer costly disruptions.","zh-TW":"擁有強大主動風險管理文化的公司遇到的高成本中斷更少。"}]', NULL, NULL, 5, 5174, NULL),
(5175, 'probation', '/prəˈbeɪʃən/', 'noun', '{"zh-TW":["試用期；考察期"],"en":["a period of testing a new employee''s suitability"]}', NULL, 'on probation / three-month probation', '[{"en":"New employees serve a three-month probation period.","zh-TW":"新員工需經過三個月的試用期。"},{"en":"His performance during probation was outstanding.","zh-TW":"他在試用期間的表現非常出色。"}]', '{"verb":"probate","adjective":"probationary"}', NULL, 3, 5175, NULL),
(5176, 'probationary period', '/prəˈbeɪʃənəri ˈpɪəriəd/', 'noun', '{"zh-TW":["試用期"],"en":["a trial period at the start of employment to assess suitability"]}', NULL, 'pass the probationary period / serve a probationary period', '[{"en":"New employees are subject to a three-month probationary period.","zh-TW":"新員工須接受三個月的試用期。"},{"en":"She passed her probationary period with excellent reviews.","zh-TW":"她以優異的評價通過了試用期。"}]', '{"adjective":"probationary"}', NULL, 5, 5176, NULL),
(5177, 'probe', '/proʊb/', 'verb', '{"zh-TW":["探查；調查"],"en":["to investigate thoroughly"]}', NULL, 'probe into / probe the issue', '[{"en":"Investigators probed into the financial fraud.","zh-TW":"調查人員深入調查財務詐欺。"},{"en":"The committee probed the matter further.","zh-TW":"委員會進一步調查此事。"}]', '{"noun":"probe"}', NULL, 2, 5177, NULL),
(5178, 'probiotics', '/''prəʊbaɪˌɒtɪks/', 'noun', '{"zh-TW":["益生菌"],"en":["live bacteria and yeasts that are beneficial to health, especially the digestive system"]}', NULL, 'take probiotics / probiotic supplement / probiotic yogurt', '[{"en":"Probiotic yogurt contains live cultures that benefit digestive health.","zh-TW":"益生菌優格含有有益於消化健康的活性菌群。"},{"en":"Doctors sometimes recommend probiotics after a course of antibiotics.","zh-TW":"醫生有時在抗生素療程後推薦服用益生菌。"}]', '{"adjective":"probiotic"}', NULL, 4, 5178, NULL),
(5179, 'probity', '/ˈprəʊbɪti/', 'noun', '{"zh-TW":["誠實正直；廉潔"],"en":["the quality of being honest and having strong moral principles"]}', NULL, 'personal probity / financial probity / public probity', '[{"en":"Public officials must demonstrate financial probity by fully disclosing their assets.","zh-TW":"公職人員必須通過充分披露其資產來展示財務廉潔性。"},{"en":"The tribunal praised the auditor for her outstanding probity and independence.","zh-TW":"法庭稱讚審計師的傑出誠信和獨立性。"}]', '{"adjective":"probity-oriented"}', NULL, 3, 5179, NULL),
(5180, 'problem', '/ˈprɒbləm/', 'noun', '{"zh-TW":["問題"],"en":["a matter that is difficult to deal with"]}', NULL, 'solve a problem / no problem', '[{"en":"We need to solve this problem quickly.","zh-TW":"我們需要快速解決這個問題。"},{"en":"No problem, I can handle it.","zh-TW":"沒問題，我可以處理。"}]', '{"noun":"problem","adjective":"problematic"}', NULL, 3, 5180, NULL),
(5181, 'problem-solving', '/ˈprɒbləm sɒlvɪŋ/', 'noun', '{"zh-TW":["解決問題；問題解決能力"],"en":["the process of finding solutions to difficult or complex issues"]}', NULL, 'problem-solving skills / creative problem-solving / problem-solving approach', '[{"en":"Her strong problem-solving skills helped the team overcome obstacles.","zh-TW":"她強大的問題解決能力幫助團隊克服了障礙。"},{"en":"Problem-solving is one of the most valued skills in the workplace.","zh-TW":"問題解決能力是職場最受重視的技能之一。"}]', '{"verb":"solve problems","adjective":"problem-solving"}', NULL, 5, 5181, NULL),
(5182, 'problem-solving skill', '/ˈprɒbləm ˌsɒlvɪŋ skɪl/', 'noun', '{"zh-TW":["問題解決技巧"],"en":["the ability to identify issues and find effective solutions through analysis and creative thinking"]}', NULL, 'develop problem-solving skills / strong problem-solving skills / use problem-solving skills', '[{"en":"Problem-solving skills are among the most valued competencies in any profession.","zh-TW":"問題解決技巧是任何職業中最受重視的能力之一。"},{"en":"She demonstrated excellent problem-solving skills by finding a creative solution to the budget crisis.","zh-TW":"她通過找到蟣決預算危機的創新方案，展示了杖出的問題解決技巧。"}]', NULL, NULL, 5, 5182, NULL),
(5183, 'problematize', '/prɒˈblemətaɪz/', 'verb', '{"zh-TW":["問題化；對…提出質疑"],"en":["to make something into or treat it as a problem"]}', NULL, 'problematize assumptions / problematize the concept / problematize power', '[{"en":"Critical theory encourages scholars to problematize taken-for-granted assumptions.","zh-TW":"批判理論鼓勵學者對理所當然的假設進行問題化。"},{"en":"The researcher problematized the category of ''race'' as a social construct.","zh-TW":"研究員對「種族」這一類別作為社會建構進行了問題化。"}]', '{"noun":"problematization","adjective":"problematized"}', NULL, 4, 5183, NULL),
(5184, 'procedure', '/prəˈsiːdʒər/', 'noun', '{"zh-TW":["程序；流程"],"en":["an established or official way of doing something"]}', NULL, 'follow procedure / standard procedure / operating procedure', '[{"en":"All complaints must be handled according to the established procedure.","zh-TW":"所有投訴必須按照既定程序處理。"},{"en":"The procedure was updated to reflect new regulatory requirements.","zh-TW":"程序已更新以反映新的監管要求。"}]', '{"plural":"procedures","adjective":"procedural"}', NULL, 3, 5184, 421),
(5185, 'proceed', '/prəˈsiːd/', 'verb', '{"zh-TW":["繼續進行","繼續；進行"],"en":["to continue with an action","to continue; to go forward"]}', '{"prefix":{"text":"pro-","meaning":"forward (向前)"},"root":{"text":"ceed","meaning":"go (走)"},"logic":"向前走，即「繼續進行」。"}', 'proceed with / proceed to / proceed as planned', '[{"en":"Please proceed to the next step.","zh-TW":"請繼續下一步。"},{"en":"The project will proceed as planned.","zh-TW":"專案將按計畫進行。"},{"en":"We will proceed with the plan as scheduled.","zh-TW":"我們將按計劃進行。"}]', '{"noun":"procedure","noun2":"proceedings","adjective":"procedural"}', NULL, 3, 5185, 181),
(5186, 'process', '/ˈprɒsɛs/', 'noun', '{"zh-TW":["過程；流程"],"en":["a series of steps; a method"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"cess","meaning":"go (走)"}}', 'hiring process / in the process of / streamline the process', '[{"en":"The hiring process takes about two weeks.","zh-TW":"招聘流程約需兩週。"},{"en":"We are in the process of upgrading the system.","zh-TW":"我們正在升級系統。"}]', '{"verb":"process","noun":"processing, processor"}', NULL, 3, 5186, 182),
(5187, 'process audit', '/ˈproʊses ˈɔːdɪt/', 'noun', '{"zh-TW":["流程審計"],"en":["an evaluation of the effectiveness and compliance of a specific process"]}', NULL, 'conduct a process audit / process audit findings', '[{"en":"A process audit confirmed the quality management system was effective.","zh-TW":"流程審計確認了品質管理系統的有效性。"},{"en":"The findings of the process audit were shared with all teams.","zh-TW":"流程審計的結果與所有團隊共享了。"}]', NULL, NULL, 5, 5187, NULL),
(5188, 'process improvement', '/ˈproʊses ɪmˈpruːvmənt/', 'noun', '{"zh-TW":["流程改善"],"en":["systematic efforts to identify and eliminate inefficiencies in work processes"]}', NULL, 'implement process improvement / process improvement initiative', '[{"en":"Process improvement reduced the order cycle time by 40%.","zh-TW":"流程改善將訂單週期時間縮短了40%。"},{"en":"The lean methodology is widely used for process improvement.","zh-TW":"精益方法論廣泛用於流程改善。"}]', NULL, NULL, 5, 5188, NULL),
(5189, 'process optimization', '/ˈprɒses ˌɒptɪmaɪˈzeɪʃən/', 'noun', '{"zh-TW":["流程優化"],"en":["improving business processes for greater efficiency"]}', NULL, 'process optimization initiative / continuous process optimization', '[{"en":"Process optimization reduced production time by 20%.","zh-TW":"流程優化將生產時間縮短了20%。"},{"en":"They hired a consultant to lead process optimization efforts.","zh-TW":"他們聘請顧問主導流程優化工作。"}]', '{"verb":"optimize","adjective":"optimized"}', NULL, 5, 5189, NULL),
(5190, 'processing', 'ˈprɒsɛsɪŋ', 'noun', '{"zh-TW":["處理；加工","辦理"],"en":["handling or treating data","the act of processing"]}', NULL, 'data processing/order processing', '[{"en":"Order processing takes one business day.","zh-TW":"訂單處理需要一個工作日。"}]', '{"verb":"process","adjective":"processed"}', NULL, 4, 5190, NULL),
(5191, 'processor', '/ˈprɒsɛsər/', 'noun', '{"zh-TW":["處理器"],"en":["the part of a computer that performs operations"]}', NULL, 'word processor / multi-core processor', '[{"en":"This laptop has a fast processor.","zh-TW":"這台筆電有一顆快速處理器。"},{"en":"The processor handles millions of calculations.","zh-TW":"處理器處理數百萬次運算。"}]', '{"verb":"process"}', NULL, 3, 5191, NULL),
(5192, 'procure', '/prəˈkjʊr/', 'verb', '{"zh-TW":["獲得；採購"],"en":["to obtain, especially with effort"]}', '{"prefix":{"text":"pro-","meaning":"for"},"root":{"text":"cure","meaning":"care (照料)"}}', 'procure supplies / procure funding', '[{"en":"The department procures supplies from local vendors.","zh-TW":"部門從當地供應商採購物資。"},{"en":"We need to procure additional funding.","zh-TW":"我們需要取得額外資金。"}]', '{"noun":"procurement"}', NULL, 3, 5192, 709),
(5193, 'procurement', '/prəˈkjʊrmənt/', 'noun', '{"zh-TW":["採購"],"en":["the process of obtaining goods or services"]}', NULL, 'procurement department / public procurement', '[{"en":"The procurement department handles all purchasing.","zh-TW":"採購部門處理所有購買事宜。"},{"en":"Public procurement must follow strict rules.","zh-TW":"公共採購必須遵循嚴格的規定。"}]', '{"noun":"procurement","verb":"procure"}', NULL, 4, 5193, 609),
(5194, 'procurement manager', '/prəˈkjʊərmənt ˈmænɪdʒər/', 'noun', '{"zh-TW":["採購經理"],"en":["a professional responsible for managing the purchasing of goods and services"]}', NULL, 'promote to procurement manager / role of procurement manager', '[{"en":"The procurement manager negotiated a 15% reduction in supplier costs.","zh-TW":"採購經理談判成功將供應商成本降低了15%。"},{"en":"A procurement manager must balance cost, quality, and delivery.","zh-TW":"採購經理必須平衡成本、品質和交貨時間。"}]', NULL, NULL, 5, 5194, NULL),
(5195, 'procurement policy', '/prəˈkjʊərmənt ˈpɒlɪsi/', 'noun', '{"zh-TW":["採購政策"],"en":["rules governing how an organization purchases goods and services"]}', NULL, 'comply with procurement policy / update the procurement policy', '[{"en":"All purchases must comply with the company procurement policy.","zh-TW":"所有採購必須遵守公司採購政策。"},{"en":"The procurement policy requires competitive bidding for contracts over 50000.","zh-TW":"採購政策要求超過5萬元的合約進行競爭性投標。"}]', NULL, NULL, 5, 5195, NULL),
(5196, 'procurement process', '/prəˈkjʊərmənt ˈprɒses/', 'noun', '{"zh-TW":["採購流程"],"en":["the complete set of steps to identify, obtain, and manage goods and services"]}', NULL, 'streamline the procurement process / procurement process efficiency', '[{"en":"The company simplified its procurement process to reduce lead times.","zh-TW":"公司簡化了其採購流程以縮短交貨期。"},{"en":"A transparent procurement process ensures fair vendor selection.","zh-TW":"透明的採購流程確保了公平的供應商選擇。"}]', NULL, NULL, 5, 5196, NULL),
(5197, 'procurement strategy', '/''prəʊˌkjʊərmənt ˌstrætədʒi/', 'noun', '{"zh-TW":["採購策略"],"en":["a plan for acquiring goods and services in a way that meets organizational goals efficiently and effectively"]}', NULL, 'develop a procurement strategy / procurement strategy review / align procurement strategy', '[{"en":"A sustainable procurement strategy prioritizes suppliers with strong environmental practices.","zh-TW":"可持續採購策略優先選擇具有強大環境實踐的供應商。"},{"en":"The company revised its procurement strategy to include more local suppliers.","zh-TW":"公司修訂了採購策略，納入了更多本地供應商。"}]', '{"noun":"procurement"}', NULL, 5, 5197, NULL),
(5198, 'prodigious', '/''prəˈdɪdʒəs/', 'adjective', '{"zh-TW":["巨大的；驚人的；非凡的"],"en":["remarkably or impressively great in extent, size, or degree"]}', NULL, 'prodigious talent / prodigious effort / prodigious output', '[{"en":"The researcher''s prodigious output of papers earned him international recognition.","zh-TW":"這位研究員令人驚嘆的論文產出贏得了他的國際聲譽。"},{"en":"Building the empire required a prodigious amount of dedication and effort.","zh-TW":"建立這個帝國需要驚人數量的奉獻和努力。"}]', '{"adverb":"prodigiously"}', NULL, 4, 5198, NULL),
(5199, 'produce', '/ˈprɒdjuːs/', 'noun', '{"zh-TW":["農產品","生產；製造","產生"],"en":["fresh fruits and vegetables","to make or manufacture","to cause"]}', '{"prefix":{"text":"pro-","meaning":"forward (向前)"},"root":{"text":"duce","meaning":"lead (引導)"},"logic":"向前引導出來的東西，即「產出」。"}', 'fresh produce / local produce; produce goods / produce results / mass-produce', '[{"en":"The supermarket has a large produce section.","zh-TW":"這間超市有很大的生鮮蔬果區。"},{"en":"We buy organic produce from local farms.","zh-TW":"我們從本地農場購買有機農產品。"},{"en":"The factory produces 10,000 units per day.","zh-TW":"工廠每天生產一萬件。"},{"en":"The campaign produced excellent results.","zh-TW":"活動產生了優秀的結果。"}]', '{"verb":"produce","noun":"production","adjective":"productive"}', NULL, 3, 5199, 47);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5200, 'product', '/ˈprɒdʌkt/', 'noun', '{"zh-TW":["產品"],"en":["something that is manufactured for sale"]}', '{"prefix":{"text":"pro-","meaning":"forward (向前)"},"root":{"text":"duct","meaning":"lead (引導)"},"logic":"被引導出來的東西，即「產品」。"}', 'new product / product launch', '[{"en":"This product is our best seller.","zh-TW":"這個產品是我們的暢銷品。"},{"en":"The company launched a new product line.","zh-TW":"公司推出了新的產品線。"}]', '{"noun":"production","verb":"produce","adjective":"productive"}', NULL, 3, 5200, NULL),
(5201, 'product development', '/ˈprɒdʌkt dɪˈveləpmənt/', 'noun', '{"zh-TW":["產品開發"],"en":["the process of creating a new product or improving an existing one"]}', NULL, 'new product development / product development cycle', '[{"en":"The product development team worked closely with customers to refine features.","zh-TW":"產品開發團隊與客戶密切合作以完善功能。"},{"en":"Rapid product development is essential in competitive technology markets.","zh-TW":"在競爭激烈的科技市場，快速的產品開發至關重要。"}]', '{"noun":"product developer"}', NULL, 5, 5201, NULL),
(5202, 'product differentiation', '/ˈprɒdʌkt ˌdɪfərənʃiˈeɪʃən/', 'noun', '{"zh-TW":["產品差異化"],"en":["making a product distinctive from competitors to attract customers"]}', NULL, 'achieve product differentiation / product differentiation strategy', '[{"en":"Product differentiation through design helped the brand charge a premium.","zh-TW":"通過設計實現的產品差異化幫助品牌收取了溢價。"},{"en":"The company invested in R&D for product differentiation.","zh-TW":"公司投資研發以實現產品差異化。"}]', NULL, NULL, 5, 5202, NULL),
(5203, 'product launch', '/ˈprɒdʌkt lɔːntʃ/', 'noun', '{"zh-TW":["產品發佈；新品上市"],"en":["the introduction of a new product to the market"]}', NULL, 'plan a product launch / successful product launch / product launch event', '[{"en":"The product launch generated significant media buzz.","zh-TW":"產品發佈引起了大量媒體關注。"},{"en":"A soft launch was planned before the full product launch.","zh-TW":"在全面產品發佈前計劃了軟啟動。"}]', '{"verb":"launch"}', NULL, 5, 5203, NULL),
(5204, 'product liability', '/ˈprɒdʌkt laɪˈæbɪlɪti/', 'noun', '{"zh-TW":["產品責任"],"en":["legal responsibility of a manufacturer for harm caused by a defective product"]}', NULL, 'face product liability claims / product liability insurance', '[{"en":"The company purchased product liability insurance to protect against claims.","zh-TW":"公司購買了產品責任保險以防範索賠。"},{"en":"A product liability lawsuit forced a costly recall.","zh-TW":"產品責任訴訟迫使進行了代價高昂的召回。"}]', NULL, NULL, 5, 5204, NULL),
(5205, 'product roadmap', '/ˈprɒdʌkt ˈroʊdmæp/', 'noun', '{"zh-TW":["產品路線圖"],"en":["a high-level visual plan showing the direction and progress of a product"]}', NULL, 'build a product roadmap / update the product roadmap', '[{"en":"The product roadmap outlines features planned for the next 12 months.","zh-TW":"產品路線圖概述了未來12個月計劃的功能。"},{"en":"Stakeholders aligned on the product roadmap at the quarterly review.","zh-TW":"利益相關者在季度審查時就產品路線圖達成一致。"}]', NULL, NULL, 5, 5205, NULL),
(5206, 'product-market fit', '/ˈprɒdʌkt ˈmɑːrkɪt fɪt/', 'noun', '{"zh-TW":["產品市場契合度"],"en":["the degree to which a product satisfies strong market demand"]}', NULL, 'achieve product-market fit / validate product-market fit', '[{"en":"The startup knew it had achieved product-market fit when retention spiked.","zh-TW":"當留存率飆升時，新創公司知道它已實現產品市場契合度。"},{"en":"Finding product-market fit is the primary goal of early-stage companies.","zh-TW":"找到產品市場契合度是早期公司的首要目標。"}]', NULL, NULL, 5, 5206, NULL),
(5207, 'production capacity', '/prəˈdʌkʃən kəˈpæsɪti/', 'noun', '{"zh-TW":["生產能力"],"en":["the maximum output a facility can produce in a given period"]}', NULL, 'increase production capacity / utilize production capacity', '[{"en":"The company doubled its production capacity with the new factory.","zh-TW":"公司通過新工廠將生產能力翻了一倍。"},{"en":"Excess production capacity leads to higher per-unit fixed costs.","zh-TW":"過剩的生產能力導致了更高的單位固定成本。"}]', NULL, NULL, 5, 5207, NULL),
(5208, 'production cycle', '/prəˈdʌkʃən ˈsaɪkəl/', 'noun', '{"zh-TW":["生產週期"],"en":["the time required to complete one cycle of manufacturing a product"]}', NULL, 'shorten the production cycle / production cycle time', '[{"en":"Automation reduced the production cycle time from 5 days to 2 days.","zh-TW":"自動化將生產週期從5天縮短到了2天。"},{"en":"A shorter production cycle improves responsiveness to customer orders.","zh-TW":"較短的生產週期改善了對客戶訂單的響應能力。"}]', NULL, NULL, 5, 5208, NULL),
(5209, 'production schedule', '/prəˈdʌkʃən ˈʃedjuːl/', 'noun', '{"zh-TW":["生產計劃；生產排程"],"en":["a plan outlining what will be produced, when, and in what quantity"]}', NULL, 'update the production schedule / follow the production schedule', '[{"en":"The production schedule was adjusted to meet the peak season demand.","zh-TW":"生產計劃調整以滿足旺季需求。"},{"en":"Disruptions in supply forced a revision to the production schedule.","zh-TW":"供應中斷迫使對生產計劃進行了修訂。"}]', NULL, NULL, 5, 5209, NULL),
(5210, 'productive', '/prəˈdʌktɪv/', 'adjective', '{"zh-TW":["有生產力的；多產的"],"en":["producing good results"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"duct","meaning":"lead (引導)"},"suffix":{"text":"-ive","meaning":"...的"}}', 'productive meeting / highly productive', '[{"en":"It was a very productive meeting.","zh-TW":"這是一個非常有成效的會議。"},{"en":"The team has been highly productive.","zh-TW":"團隊生產力很高。"}]', '{"noun":"productivity","adverb":"productively"}', NULL, 4, 5210, NULL),
(5211, 'productivity', '/ˌprɒdʌkˈtɪvɪti/', 'noun', '{"zh-TW":["生產力；效率"],"en":["the rate at which work is completed efficiently"]}', NULL, 'increase productivity / productivity tools', '[{"en":"Remote work tools have boosted employee productivity.","zh-TW":"遠端工作工具提升了員工生產力。"},{"en":"Low morale often leads to reduced productivity.","zh-TW":"士氣低落往往導致生產力下降。"}]', '{"adjective":"productive","adverb":"productively"}', NULL, 4, 5211, 422),
(5212, 'productivity hack', '/''prɒdʌktɪvɪti hæk/', 'noun', '{"zh-TW":["生產力技巧；提效小技"],"en":["a method or technique for increasing efficiency and output in work or daily activities"]}', NULL, 'try a productivity hack / useful productivity hack / popular productivity hack', '[{"en":"Using the Pomodoro technique is a popular productivity hack for focused work sessions.","zh-TW":"使用番茄工作法是一種用於專注工作的流行生產力技巧。"},{"en":"She shared her favorite productivity hacks with her team to improve their workflow.","zh-TW":"她與團隊分享了她最喜歡的生產力技巧，以改善他們的工作流程。"}]', '{"noun":"productivity"}', NULL, 5, 5212, NULL),
(5213, 'productivity improvement', '/ˌprɒdʌkˈtɪvɪti ɪmˈpruːvmənt/', 'noun', '{"zh-TW":["生產力改善"],"en":["actions taken to increase output per unit of input"]}', NULL, 'drive productivity improvement / productivity improvement program', '[{"en":"Automation led to a 25% productivity improvement.","zh-TW":"自動化帶來了25%的生產力改善。"},{"en":"The productivity improvement program reduced manufacturing costs significantly.","zh-TW":"生產力改善計劃顯著降低了製造成本。"}]', NULL, NULL, 5, 5213, NULL),
(5214, 'profession', '/prəˈfɛʃən/', 'noun', '{"zh-TW":["職業；專業"],"en":["a type of job requiring special training"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"fess","meaning":"declare (宣稱)"},"suffix":{"text":"-ion","meaning":"名詞後綴"}}', 'by profession / medical profession / enter a profession', '[{"en":"She is a lawyer by profession.","zh-TW":"她的職業是律師。"},{"en":"He entered the teaching profession.","zh-TW":"他進入了教學行業。"}]', '{"adjective":"professional","adverb":"professionally","noun":"professional"}', NULL, 4, 5214, NULL),
(5215, 'professional', 'prəˈfɛʃənəl', 'adjective', '{"zh-TW":["專業的；職業的","稱職的"],"en":["relating to a profession","skilled and competent"]}', NULL, 'professional development/professional manner', '[{"en":"Always maintain a professional manner.","zh-TW":"始終保持專業態度。"}]', '{"noun":"professional","adverb":"professionally"}', NULL, 4, 5215, 183),
(5216, 'professional development', '/prəˈfeʃənl dɪˈveləpmənt/', 'noun', '{"zh-TW":["職業發展；專業進修"],"en":["activities that enhance professional knowledge, skills, and competencies"]}', NULL, 'invest in professional development / professional development plan / continuous professional development', '[{"en":"The company offers an annual budget for employee professional development.","zh-TW":"公司為員工職業發展提供年度預算。"},{"en":"Professional development is essential for staying current in a rapidly changing field.","zh-TW":"在快速變化的領域保持競爭力，職業發展至關重要。"}]', '{"adjective":"professionally developed"}', NULL, 5, 5216, NULL),
(5217, 'professionalism', 'prəˈfɛʃənəlɪzəm', 'noun', '{"zh-TW":["專業精神；職業道德","行為規範"],"en":["the conduct expected in a profession","high standards of behavior"]}', NULL, 'show professionalism/maintain professionalism', '[{"en":"Professionalism is expected at all times.","zh-TW":"始終期望展現專業精神。"}]', '{"adjective":"professional","adverb":"professionally"}', NULL, 5, 5217, NULL),
(5218, 'professor', '/prəˈfɛsər/', 'noun', '{"zh-TW":["教授"],"en":["a senior university teacher"]}', NULL, 'assistant professor / professor of history', '[{"en":"The professor published a new paper.","zh-TW":"教授發表了一篇新論文。"},{"en":"She''s a professor of biology.","zh-TW":"她是生物學教授。"}]', NULL, NULL, 3, 5218, NULL),
(5219, 'proficient', '/''prəˈfɪʃənt/', 'adjective', '{"zh-TW":["熟練的；精通的"],"en":["competent or skilled in doing or using something"]}', NULL, 'proficient in English / proficient user / become proficient', '[{"en":"Candidates should be proficient in Microsoft Excel and data analysis tools.","zh-TW":"候選人應熟練掌握Microsoft Excel和數據分析工具。"},{"en":"She became proficient in Python after completing an online course.","zh-TW":"她在完成一門網上課程後熟練掌握了Python。"}]', '{"adverb":"proficiently","noun":"proficiency"}', NULL, 4, 5219, NULL),
(5220, 'profile', '/ˈproʊfaɪl/', 'noun', '{"zh-TW":["簡介；概況","形象"],"en":["a description of characteristics","public image"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"fil","meaning":"thread, line (線)"}}', 'company profile / high-profile / raise one''s profile', '[{"en":"Please update your employee profile.","zh-TW":"請更新你的員工資料。"},{"en":"The company maintains a high profile in the industry.","zh-TW":"公司在業界保持高知名度。"}]', '{"verb":"profile","adjective":"high-profile, low-profile"}', NULL, 3, 5220, 184),
(5221, 'profit', '/ˈprɒfɪt/', 'noun', '{"zh-TW":["利潤；收益"],"en":["money gained from business"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"fit","meaning":"make (做)"}}', 'net profit / profit margin / make a profit', '[{"en":"The company made a profit of $1 million.","zh-TW":"公司獲利一百萬美元。"},{"en":"Profit margins have been shrinking.","zh-TW":"利潤率一直在縮減。"}]', '{"adjective":"profitable","noun":"profitability","verb":"profit"}', NULL, 2, 5221, 423),
(5222, 'profit and loss account', '/ˈprɒfɪt ænd lɒs əˈkaʊnt/', 'noun', '{"zh-TW":["損益帳；利潤表"],"en":["a financial statement showing revenues, expenses, and profit over a period"]}', NULL, 'review the profit and loss account / analyze the P&L', '[{"en":"The profit and loss account showed a net profit of 8 million.","zh-TW":"損益帳顯示淨利潤為800萬元。"},{"en":"Monthly profit and loss accounts are reviewed by the finance team.","zh-TW":"財務團隊每月審查損益帳。"}]', '{"abbreviation":"P&L"}', NULL, 5, 5222, NULL),
(5223, 'profit center', '/ˈprɒfɪt ˈsentər/', 'noun', '{"zh-TW":["利潤中心"],"en":["a division or segment of a company expected to generate profit"]}', NULL, 'manage a profit center / profit center performance', '[{"en":"Each regional office operates as a profit center.","zh-TW":"每個區域辦公室作為利潤中心運營。"},{"en":"Profit center managers are accountable for both revenue and costs.","zh-TW":"利潤中心管理者對收入和成本均負有責任。"}]', NULL, NULL, 5, 5223, NULL),
(5224, 'profit margin', '/ˈprɒfɪt ˈmɑːrdʒɪn/', 'noun', '{"zh-TW":["利潤率"],"en":["the percentage of revenue remaining after costs"]}', NULL, 'improve profit margin / thin profit margin', '[{"en":"The company maintained a healthy profit margin despite competition.","zh-TW":"儘管面臨競爭，公司仍維持健康的利潤率。"},{"en":"A low profit margin can indicate high operating costs.","zh-TW":"低利潤率可能表示較高的運營成本。"}]', NULL, NULL, 5, 5224, NULL),
(5225, 'profit margin improvement', '/ˈprɒfɪt ˈmɑːrdʒɪn ɪmˈpruːvmənt/', 'noun', '{"zh-TW":["利潤率改善"],"en":["efforts to increase the percentage of profit relative to revenue"]}', NULL, 'focus on profit margin improvement / profit margin improvement strategy', '[{"en":"Cost-cutting measures contributed to a profit margin improvement of 3%.","zh-TW":"削減成本措施促成了3%的利潤率改善。"},{"en":"Automation is key to the company''s profit margin improvement plan.","zh-TW":"自動化是公司利潤率改善計劃的關鍵。"}]', NULL, NULL, 5, 5225, NULL),
(5226, 'profit motive', '/ˈprɒfɪt ˈmoʊtɪv/', 'noun', '{"zh-TW":["逐利動機；利潤驅動"],"en":["the incentive of financial gain driving economic activity"]}', NULL, 'driven by profit motive / profit motive in business', '[{"en":"The profit motive encourages companies to operate efficiently.","zh-TW":"逐利動機促使公司高效運營。"},{"en":"Critics argue the profit motive can conflict with social responsibility.","zh-TW":"批評者認為逐利動機可能與社會責任相衝突。"}]', NULL, NULL, 5, 5226, NULL),
(5227, 'profit sharing', '/ˈprɒfɪt ˈʃeərɪŋ/', 'noun', '{"zh-TW":["利潤分享；分紅"],"en":["a scheme where employees receive a share of the company''s profits"]}', NULL, 'profit sharing plan / profit sharing bonus / introduce profit sharing', '[{"en":"The profit sharing plan motivated employees to improve company performance.","zh-TW":"利潤分享計劃激勵員工改善公司績效。"},{"en":"All staff received a profit sharing bonus after the record year.","zh-TW":"創紀錄的一年後，所有員工都獲得了利潤分享獎金。"}]', NULL, NULL, 5, 5227, NULL),
(5228, 'profit warning', '/ˈprɒfɪt ˈwɔːrnɪŋ/', 'noun', '{"zh-TW":["盈利預警"],"en":["a public announcement that profits will be lower than expected"]}', NULL, 'issue a profit warning / receive a profit warning', '[{"en":"The company issued a profit warning after weak Q3 sales.","zh-TW":"公司在第三季度銷售疲弱後發出了盈利預警。"},{"en":"A profit warning typically leads to a sharp drop in share price.","zh-TW":"盈利預警通常導致股價大幅下跌。"}]', NULL, NULL, 5, 5228, NULL),
(5229, 'profit-sharing plan', '/ˈprɒfɪt ˈʃeərɪŋ plæn/', 'noun', '{"zh-TW":["利潤分享計劃"],"en":["a program in which employees receive a share of company profits"]}', NULL, 'implement a profit-sharing plan / profit-sharing plan contribution', '[{"en":"The profit-sharing plan increased employee motivation significantly.","zh-TW":"利潤分享計劃顯著提高了員工積極性。"},{"en":"Employees received a bonus under the company''s profit-sharing plan.","zh-TW":"員工根據公司的利潤分享計劃收到了獎金。"}]', NULL, NULL, 5, 5229, NULL),
(5230, 'profitability', 'ˌprɒfɪtəˈbɪlɪti', 'noun', '{"zh-TW":["獲利能力；盈利性","收益"],"en":["the ability to generate profit","financial success"]}', NULL, 'improve profitability/measure profitability', '[{"en":"Improving profitability is a key goal.","zh-TW":"提高獲利能力是主要目標。"}]', '{"adjective":"profitable","adverb":"profitably"}', NULL, 5, 5230, 807),
(5231, 'profitability analysis', '/ˌprɒfɪtəˈbɪlɪti əˈnæləsɪs/', 'noun', '{"zh-TW":["盈利能力分析"],"en":["a financial assessment of how profitable a business, product, or customer is"]}', NULL, 'conduct profitability analysis / profitability analysis by segment', '[{"en":"Profitability analysis showed that three product lines drove 80% of earnings.","zh-TW":"盈利能力分析顯示三條產品線帶來了80%的收益。"},{"en":"The team conducted a customer profitability analysis to prioritize retention.","zh-TW":"團隊進行了客戶盈利能力分析以確定留存優先順序。"}]', NULL, NULL, 5, 5231, NULL),
(5232, 'profitable', '/ˈprɒfɪtəbl/', 'adjective', '{"zh-TW":["有利可圖的；盈利的"],"en":["generating a profit or financial gain"]}', NULL, 'profitable business / highly profitable / profitable venture', '[{"en":"The new product line proved highly profitable in its first year.","zh-TW":"新產品線在第一年被證明是高度有利可圖的。"},{"en":"The company focused on its most profitable segments.","zh-TW":"公司專注於其最有利可圖的細分市場。"}]', '{"adverb":"profitably","noun":"profitability","antonym":"unprofitable"}', NULL, 4, 5232, NULL),
(5233, 'proforma invoice', '/ˌprəʊˈfɔːrmə ˈɪnvɔɪs/', 'noun', '{"zh-TW":["形式發票；估價發票"],"en":["a preliminary invoice issued before confirming full details of the transaction"]}', NULL, 'issue a proforma invoice / proforma invoice approval', '[{"en":"The supplier sent a proforma invoice to confirm pricing and quantities.","zh-TW":"供應商發送了形式發票以確認定價和數量。"},{"en":"A proforma invoice is required to open a letter of credit.","zh-TW":"開立信用狀需要形式發票。"}]', NULL, NULL, 5, 5233, NULL),
(5234, 'profound', '/prəˈfaʊnd/', 'adjective', '{"zh-TW":["深刻的；深遠的"],"en":["very great or intense"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"found","meaning":"bottom (底部)"}}', 'profound impact / profound effect / profound change', '[{"en":"Technology has had a profound impact on business.","zh-TW":"科技對商業有深遠影響。"},{"en":"The changes are profound and lasting.","zh-TW":"這些變化是深刻且持久的。"}]', '{"adverb":"profoundly","noun":"profundity"}', NULL, 3, 5234, NULL),
(5235, 'prognosis', '/prɒɡˈnəʊsɪs/', 'noun', '{"zh-TW":["預後；預測"],"en":["a forecast of the likely course and outcome of a disease"]}', NULL, 'favorable prognosis / poor prognosis / prognosis for recovery', '[{"en":"The doctor gave a cautiously optimistic prognosis for recovery.","zh-TW":"醫生對康復給出了謹慎樂觀的預後。"},{"en":"Early diagnosis significantly improves the prognosis for most cancers.","zh-TW":"早期診斷顯著改善了大多數癌症的預後。"}]', '{"adjective":"prognostic","verb":"prognosticate"}', NULL, 3, 5235, NULL),
(5236, 'program', '/ˈproʊɡræm/', 'noun', '{"zh-TW":["計劃；方案","程式"],"en":["a planned series of activities","software"]}', NULL, 'training program / program development / government program', '[{"en":"The company launched a new training program.","zh-TW":"公司推出了新培訓計劃。"},{"en":"She manages the employee wellness program.","zh-TW":"她管理員工健康方案。"}]', '{"verb":"program","noun":"programmer, programming"}', NULL, 3, 5236, NULL),
(5237, 'progress', '/ˈprɒɡrɛs/', 'noun', '{"zh-TW":["進展；進步"],"en":["forward movement; development"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"gress","meaning":"step (步)"}}', 'make progress / in progress / progress report', '[{"en":"We have made significant progress this month.","zh-TW":"本月我們取得了重大進展。"},{"en":"The project is still in progress.","zh-TW":"項目仍在進行中。"}]', '{"verb":"progress","adjective":"progressive","adverb":"progressively"}', NULL, 3, 5237, 424),
(5238, 'progress report', '/ˈprɒɡres rɪˈpɔːrt/', 'noun', '{"zh-TW":["進度報告"],"en":["a formal document summarizing work completed and remaining on a project"]}', NULL, 'submit a progress report / monthly progress report / progress report template', '[{"en":"The progress report showed 70% of tasks were completed on time.","zh-TW":"進度報告顯示70%的任務按時完成。"},{"en":"Monthly progress reports are submitted to the steering committee.","zh-TW":"月度進度報告提交給指導委員會。"}]', NULL, NULL, 5, 5238, NULL),
(5239, 'prohibit', '/prəˈhɪbɪt/', 'verb', '{"zh-TW":["禁止"],"en":["to officially forbid","to officially ban"]}', '{"prefix":{"text":"pro-","meaning":"before"},"root":{"text":"hibit","meaning":"hold (持有)"}}', 'prohibit sb. from / strictly prohibited; strictly prohibited / prohibited by law', '[{"en":"Smoking is prohibited in all buildings.","zh-TW":"所有建築物內禁止吸煙。"},{"en":"The law prohibits discrimination.","zh-TW":"法律禁止歧視。"},{"en":"Photography is strictly prohibited.","zh-TW":"嚴禁拍照。"},{"en":"The use of mobile phones is prohibited.","zh-TW":"禁止使用手機。"}]', '{"noun":"prohibition","adjective":"prohibitive"}', NULL, 3, 5239, 710),
(5240, 'project', '/ˈprɒdʒɛkt/', 'noun', '{"zh-TW":["專案；項目"],"en":["a planned piece of work"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"ject","meaning":"throw (投擲)"}}', 'project management / project deadline / project team', '[{"en":"The project is expected to be completed by June.","zh-TW":"項目預計六月完成。"},{"en":"She leads a team of five on the project.","zh-TW":"她帶領五人團隊做該項目。"}]', '{"verb":"project","noun":"projection, projector"}', NULL, 3, 5240, 185),
(5241, 'project brief', '/ˈprɒdʒekt briːf/', 'noun', '{"zh-TW":["專案摘要；項目簡介"],"en":["a short document defining the goals, scope, and deliverables of a project"]}', NULL, 'prepare a project brief / review the project brief', '[{"en":"The project brief was circulated to all stakeholders for approval.","zh-TW":"專案摘要已分發給所有利害關係人以獲取批准。"},{"en":"A detailed project brief prevents misunderstandings later.","zh-TW":"詳細的專案摘要可防止以後產生誤解。"}]', NULL, NULL, 5, 5241, NULL),
(5242, 'project charter', '/ˈprɒdʒekt ˈtʃɑːrtər/', 'noun', '{"zh-TW":["項目章程"],"en":["a document authorizing a project and outlining its objectives and scope"]}', NULL, 'write a project charter / project charter template / approve the project charter', '[{"en":"The project charter was signed by the sponsor before kickoff.","zh-TW":"項目章程在啟動前由贊助人簽署。"},{"en":"A clear project charter aligns stakeholders from the start.","zh-TW":"清晰的項目章程從一開始就使利益相關者保持一致。"}]', NULL, NULL, 5, 5242, NULL),
(5243, 'project deliverable', '/ˈprɒdʒekt dɪˈlɪvərəbəl/', 'noun', '{"zh-TW":["項目可交付成果；項目交付物"],"en":["a specific, tangible output or result that must be produced as part of a project"]}', NULL, 'complete a project deliverable / define project deliverables / submit project deliverables', '[{"en":"Each team member was assigned specific project deliverables with clear deadlines.","zh-TW":"每位團隊成員都被指定了具有明確截止日期的特定項目交付物。"},{"en":"The project deliverable was submitted on time and exceeded the client''s expectations.","zh-TW":"項目交付物按時提交，并超越了客戶的期望。"}]', NULL, NULL, 5, 5243, NULL),
(5244, 'project kickoff', '/ˈprɒdʒekt ˈkɪkɒf/', 'noun', '{"zh-TW":["項目啟動"],"en":["the initial meeting that officially starts a project and aligns the team"]}', NULL, 'host a project kickoff / project kickoff meeting', '[{"en":"The project kickoff meeting introduced the timeline and responsibilities.","zh-TW":"項目啟動會議介紹了時間表和職責。"},{"en":"All stakeholders attended the project kickoff to align on expectations.","zh-TW":"所有利害關係人出席了項目啟動會議以對齊期望。"}]', NULL, NULL, 5, 5244, NULL),
(5245, 'project lifecycle', '/ˈprɒdʒekt ˈlaɪfsaɪkəl/', 'noun', '{"zh-TW":["項目生命週期"],"en":["the phases a project passes through from initiation to closure"]}', NULL, 'manage the project lifecycle / project lifecycle phases', '[{"en":"Each phase of the project lifecycle has defined deliverables.","zh-TW":"項目生命週期的每個階段都有明確的交付成果。"},{"en":"Understanding the project lifecycle improves planning and risk management.","zh-TW":"理解項目生命週期改善了計劃和風險管理。"}]', NULL, NULL, 5, 5245, NULL),
(5246, 'project management', '/ˈprɒdʒekt ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["項目管理"],"en":["the process of planning, executing, and closing projects effectively"]}', NULL, 'project management methodology / project management software / project management skills', '[{"en":"Strong project management kept the initiative on time and on budget.","zh-TW":"強大的項目管理使計劃按時按預算完成。"},{"en":"She earned a project management certification to advance her career.","zh-TW":"她獲得了項目管理認證以推進職業生涯。"}]', '{"noun":"project manager","abbreviation":"PM"}', NULL, 5, 5246, NULL),
(5247, 'project manager', '/ˈprɒdʒɛkt ˈmænɪdʒər/', 'noun', '{"zh-TW":["項目經理"],"en":["a person responsible for overseeing a project"]}', NULL, 'experienced project manager / appoint a project manager', '[{"en":"The project manager ensured all deadlines were met.","zh-TW":"項目經理確保所有截止日期都能達成。"},{"en":"A skilled project manager keeps the team on track.","zh-TW":"有技能的項目經理使團隊保持正軌。"}]', NULL, NULL, 5, 5247, NULL),
(5248, 'project milestone', '/ˈprɒdʒekt ˈmaɪlstəʊn/', 'noun', '{"zh-TW":["項目裡程碑"],"en":["a significant event or achievement in a project that marks the completion of a major phase or goal"]}', NULL, 'reach a project milestone / set a project milestone / project milestone deadline', '[{"en":"The team celebrated reaching an important project milestone ahead of schedule.","zh-TW":"團隊慶祝提前達成重要的項目裡程碑。"},{"en":"Each project milestone was reviewed by the steering committee before proceeding to the next phase.","zh-TW":"在進入下一階段之前，指導委員會审查了每個項目裡程碑。"}]', NULL, NULL, 5, 5248, NULL),
(5249, 'project portfolio', '/ˈprɒdʒekt pɔːrtˈfoʊlioʊ/', 'noun', '{"zh-TW":["專案組合"],"en":["the collection of projects being managed simultaneously by an organization"]}', NULL, 'manage a project portfolio / project portfolio review', '[{"en":"The PMO manages a project portfolio of over 20 active initiatives.","zh-TW":"項目管理辦公室管理著超過20個活躍倡議的專案組合。"},{"en":"A balanced project portfolio aligns with strategic business goals.","zh-TW":"均衡的專案組合與戰略業務目標保持一致。"}]', NULL, NULL, 5, 5249, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5250, 'project scope', '/ˈprɒdʒɛkt skəʊp/', 'noun', '{"zh-TW":["項目範圍"],"en":["the defined work and deliverables of a project"]}', NULL, 'define the project scope / project scope creep', '[{"en":"The project scope was clearly defined at the kickoff meeting.","zh-TW":"項目範圍在啟動會議上明確界定了。"},{"en":"Scope creep can cause delays and budget overruns.","zh-TW":"範圍蔓延可能導致延誤和預算超支。"}]', NULL, NULL, 5, 5250, NULL),
(5251, 'project sponsor', '/ˈprɒdʒekt ˈspɒnsər/', 'noun', '{"zh-TW":["項目發起人；項目贊助人"],"en":["a senior executive who champions and is accountable for a project''s success"]}', NULL, 'role of the project sponsor / project sponsor responsibilities', '[{"en":"The project sponsor secured the funding for the new IT system.","zh-TW":"項目發起人為新IT系統爭取到了資金。"},{"en":"The project sponsor escalated the resource issue to the board.","zh-TW":"項目發起人將資源問題上報給了董事會。"}]', NULL, NULL, 5, 5251, NULL),
(5252, 'project team', '/ˈprɒdʒekt tiːm/', 'noun', '{"zh-TW":["項目團隊"],"en":["a group of individuals assembled to work on a specific project"]}', NULL, 'lead a project team / project team meeting', '[{"en":"The project team met weekly to review progress and resolve issues.","zh-TW":"項目團隊每週開會審查進度並解決問題。"},{"en":"A strong project team is key to delivering on time and on budget.","zh-TW":"強大的項目團隊是按時按預算交付的關鍵。"}]', NULL, NULL, 4, 5252, NULL),
(5253, 'projected earnings', '/prəˈdʒektɪd ˈɜːrnɪŋz/', 'noun', '{"zh-TW":["預計盈利"],"en":["an estimate of future profits based on current trends and assumptions"]}', NULL, 'forecast projected earnings / meet projected earnings', '[{"en":"Analysts raised projected earnings after the strong Q2 results.","zh-TW":"在強勁的第二季度業績後，分析師上調了預計盈利。"},{"en":"Missing projected earnings can trigger a sharp stock price decline.","zh-TW":"未達預計盈利可能觸發股價急跌。"}]', NULL, NULL, 5, 5253, NULL),
(5254, 'projected revenue', '/prəˈdʒektɪd ˈrevɪnjuː/', 'noun', '{"zh-TW":["預計收入"],"en":["estimated future revenue based on historical data and market analysis"]}', NULL, 'calculate projected revenue / projected revenue shortfall', '[{"en":"The projected revenue for next year was set at $50 million.","zh-TW":"明年的預計收入定為5000萬元。"},{"en":"Actual results fell below projected revenue due to market slowdown.","zh-TW":"由於市場放緩，實際結果低於預計收入。"}]', NULL, NULL, 5, 5254, NULL),
(5255, 'proliferate', '/''prəˈlɪfəreɪt/', 'verb', '{"zh-TW":["激增；大量繁殖"],"en":["to increase rapidly in numbers or amount; to spread widely"]}', NULL, 'proliferate rapidly / proliferate in / ideas proliferate', '[{"en":"Social media platforms proliferated in the 2010s, changing how people communicate.","zh-TW":"社交媒體平台在2010年代激增，改變了人們的溝通方式。"},{"en":"Counterfeit products have proliferated in online markets.","zh-TW":"仿冒品在網絡市場大量增加。"}]', '{"noun":"proliferation","adjective":"proliferating"}', NULL, 4, 5255, NULL),
(5256, 'prolific', '/prəˈlɪfɪk/', 'adjective', '{"zh-TW":["多產的；豐碩的"],"en":["producing many works or results; abundant"]}', NULL, 'prolific writer / prolific researcher / prolific output', '[{"en":"She is a prolific author who publishes three books per year.","zh-TW":"她是一位多產的作家，每年出版三本書。"},{"en":"The lab has been prolific in producing groundbreaking research.","zh-TW":"該實驗室在產出開創性研究方面十分多產。"}]', '{"adverb":"prolifically"}', NULL, 3, 5256, NULL),
(5257, 'prolong', '/prəˈlɒŋ/', 'verb', '{"zh-TW":["延長；拖延"],"en":["to make something last longer"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"long","meaning":"long (長)"}}', 'prolong the discussion / prolonged period', '[{"en":"We should not prolong the negotiations.","zh-TW":"我們不應拖延談判。"},{"en":"The prolonged delay caused concern.","zh-TW":"長期延誤引起了擔憂。"}]', '{"adjective":"prolonged","noun":"prolongation"}', NULL, 3, 5257, NULL),
(5258, 'prominent', '/ˈprɒmɪnənt/', 'adjective', '{"zh-TW":["傑出的；顯著的"],"en":["important; well-known"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"min","meaning":"project (突出)"},"suffix":{"text":"-ent","meaning":"...的"}}', 'prominent figure / prominent role / prominently displayed', '[{"en":"She is a prominent figure in the industry.","zh-TW":"她是業界的傑出人物。"},{"en":"The brand is prominently displayed.","zh-TW":"品牌被醒目地展示。"}]', '{"adverb":"prominently","noun":"prominence"}', NULL, 3, 5258, NULL),
(5259, 'promise', '/ˈprɒmɪs/', 'verb', '{"zh-TW":["承諾；保證"],"en":["to tell someone you will do something"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"mis","meaning":"send (送)"}}', 'make a promise / promise to do / show promise', '[{"en":"The company promised to deliver by Monday.","zh-TW":"公司承諾週一前送達。"},{"en":"The new employee shows great promise.","zh-TW":"新員工展現出很大潛力。"}]', '{"noun":"promise","adjective":"promising"}', NULL, 3, 5259, NULL),
(5260, 'promissory note', '/ˈprɒmɪsɔːri noʊt/', 'noun', '{"zh-TW":["本票；期票"],"en":["a written promise to pay a specific sum of money at a specified date"]}', NULL, 'issue a promissory note / promissory note amount', '[{"en":"The borrower signed a promissory note committing to repay the loan.","zh-TW":"借款人簽署了一份承諾償還貸款的本票。"},{"en":"A promissory note is a negotiable instrument transferable to third parties.","zh-TW":"本票是可轉讓給第三方的流通票據。"}]', NULL, NULL, 5, 5260, NULL),
(5261, 'promote', '/prəˈmoʊt/', 'verb', '{"zh-TW":["促進；推廣","晉升"],"en":["to help something develop","to give higher rank"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"mote","meaning":"move (移動)"}}', 'promote a product / get promoted / promote growth', '[{"en":"She was promoted to senior manager.","zh-TW":"她被晉升為高級經理。"},{"en":"We need to promote the new product line.","zh-TW":"我們需要推廣新產品線。"}]', '{"noun":"promotion, promoter","adjective":"promotional"}', NULL, 3, 5261, 186),
(5262, 'promotion', '/prəˈmoʊʃn/', 'noun', '{"zh-TW":["促銷；升遷"],"en":["advertising activity","advancement in rank or position"]}', '{"prefix":{"text":"pro-","meaning":"forward (向前)"},"root":{"text":"mot","meaning":"move (移動)"},"suffix":{"text":"-ion","meaning":"act of (行為)"},"logic":"向前推動的行為，即「促銷」或「升遷」。"}', 'sales promotion / get a promotion', '[{"en":"The store is running a buy-one-get-one promotion.","zh-TW":"商店正在舉辦買一送一的促銷活動。"},{"en":"She received a promotion to senior manager.","zh-TW":"她被升為資深經理。"}]', '{"verb":"promote","adjective":"promotional"}', NULL, 3, 5262, 611),
(5263, 'promotional offer', '/prəˈmoʊʃənl ˈɒfər/', 'noun', '{"zh-TW":["促銷優惠"],"en":["a temporary discount or special deal designed to boost sales"]}', NULL, 'launch a promotional offer / promotional offer period', '[{"en":"The promotional offer attracted 500 new customers in one week.","zh-TW":"促銷優惠在一週內吸引了500名新客戶。"},{"en":"Promotional offers are typically time-limited to create urgency.","zh-TW":"促銷優惠通常是有時間限制的，以製造緊迫感。"}]', NULL, NULL, 5, 5263, NULL),
(5264, 'prompt', '/prɒmpt/', 'adjective', '{"zh-TW":["迅速的；及時的"],"en":["done quickly; immediate"]}', NULL, 'prompt response / prompt delivery / prompt action', '[{"en":"Thank you for your prompt response.","zh-TW":"感謝你的迅速回覆。"},{"en":"Prompt action is required.","zh-TW":"需要立即行動。"}]', '{"adverb":"promptly","verb":"prompt","noun":"promptness"}', NULL, 2, 5264, NULL),
(5265, 'promulgate', '/ˈprɒməlɡeɪt/', 'verb', '{"zh-TW":["頒布；宣揚；傳播"],"en":["to make known officially; to promote ideas widely"]}', NULL, 'promulgate a law / promulgate regulations / promulgate a policy', '[{"en":"The government promulgated new environmental regulations.","zh-TW":"政府頒布了新的環境法規。"},{"en":"The organization promulgated its code of conduct to all staff.","zh-TW":"該組織向所有員工宣傳其行為準則。"}]', '{"noun":"promulgation"}', NULL, 4, 5265, NULL),
(5266, 'pronunciation guide', '/''prəˌnʌnsiˌeɪʃən ɡaɪd/', 'noun', '{"zh-TW":["發音指南；讀音指導"],"en":["a resource that explains how to pronounce words correctly in a given language"]}', NULL, 'consult a pronunciation guide / pronunciation guide for beginners / follow a pronunciation guide', '[{"en":"The language app includes a pronunciation guide with audio examples for every word.","zh-TW":"這個語言應用程序包含每個單詞的帶音頻示例的發音指南。"},{"en":"She used the pronunciation guide in the textbook to master difficult sounds in French.","zh-TW":"她使用教科書中的發音指南來掌握法語中的難發音。"}]', '{"noun":"pronunciation"}', NULL, 5, 5266, NULL),
(5267, 'proof', '/pruːf/', 'noun', '{"zh-TW":["證據；證明"],"en":["evidence that shows something is true"]}', NULL, 'proof of identity / burden of proof / proof of purchase', '[{"en":"You need proof of identity to open an account.","zh-TW":"開戶需要身分證明。"},{"en":"Keep the receipt as proof of purchase.","zh-TW":"保留收據作為購買證明。"}]', '{"verb":"prove","adjective":"proven"}', NULL, 2, 5267, NULL),
(5268, 'proof of concept', '/pruːf əv ˈkɒnsept/', 'noun', '{"zh-TW":["概念驗證"],"en":["a demonstration to test an idea or method before full-scale implementation"]}', NULL, 'build a proof of concept / proof of concept stage / proof of concept project', '[{"en":"The team built a proof of concept to validate the technical approach.","zh-TW":"團隊構建了概念驗證以驗證技術方法。"},{"en":"A successful proof of concept convinced management to fund the full project.","zh-TW":"成功的概念驗證說服管理層資助完整項目。"}]', NULL, NULL, 5, 5268, NULL),
(5269, 'proofread', '/ˈpruːfriːd/', 'verb', '{"zh-TW":["校對；校讀"],"en":["to read and correct errors in a document"]}', NULL, 'proofread a document / proofread before submitting', '[{"en":"Always proofread your report before submitting it.","zh-TW":"提交前務必校對您的報告。"},{"en":"She proofread the contract carefully for errors.","zh-TW":"她仔細校對了合約中的錯誤。"}]', '{"noun":"proofreader","adjective":"proofread"}', NULL, 3, 5269, NULL),
(5270, 'propensity', '/prəˈpensɪti/', 'noun', '{"zh-TW":["傾向；癖好"],"en":["a natural tendency to behave in a particular way"]}', NULL, 'propensity to consume / propensity for risk / natural propensity', '[{"en":"His propensity for procrastination affected his productivity.","zh-TW":"他拖延的傾向影響了他的生產力。"},{"en":"There is a clear propensity for prices to rise during peak season.","zh-TW":"在旺季，價格有明顯的上漲傾向。"}]', NULL, NULL, 4, 5270, NULL),
(5271, 'proper', '/ˈprɒpər/', 'adjective', '{"zh-TW":["適當的；正確的"],"en":["suitable; correct"]}', NULL, 'proper procedure / proper way / proper training', '[{"en":"Please follow the proper procedure.","zh-TW":"請遵循適當程序。"},{"en":"All staff must receive proper training.","zh-TW":"所有員工須接受適當培訓。"}]', '{"adverb":"properly"}', NULL, 2, 5271, NULL),
(5272, 'property', '/ˈprɒpərti/', 'noun', '{"zh-TW":["財產；房產","特性"],"en":["something owned","a characteristic"]}', '{"root":{"text":"propri","meaning":"own (擁有)"},"suffix":{"text":"-ty","meaning":"狀態"}}', 'intellectual property / property management / property value', '[{"en":"The company owns several properties downtown.","zh-TW":"公司在市中心擁有幾處房產。"},{"en":"Intellectual property must be protected.","zh-TW":"智慧財產權必須受到保護。"}]', NULL, NULL, 3, 5272, 425),
(5273, 'property deed', '/''prɒpərti diːd/', 'noun', '{"zh-TW":["房產契約；不動產所有權書"],"en":["a legal document that transfers ownership of real estate from one party to another"]}', NULL, 'transfer a property deed / property deed records / sign a property deed', '[{"en":"The property deed was signed at the notary''s office in the presence of both parties.","zh-TW":"房產契約在雙方的見證下在公證處簽署。"},{"en":"She discovered an error in the property deed and had to have it corrected legally.","zh-TW":"她發現房產契約中有一個錯誤，不得不依法更正。"}]', '{"noun2":"deed","verb":"deed"}', NULL, 5, 5273, NULL),
(5274, 'property developer', '/''prɒpərti dɪˌveləpər/', 'noun', '{"zh-TW":["房地產開發商；地產開發商"],"en":["a company or person that builds, renovates, or converts properties for sale or rental"]}', NULL, 'experienced property developer / property developer project / large property developer', '[{"en":"The property developer transformed an old warehouse into luxury loft apartments.","zh-TW":"房地產開發商將一個舊倉庫改造成豪華閣樓公寓。"},{"en":"The property developer broke ground on the new residential complex last month.","zh-TW":"房地產開發商上個月為新住宅大樓破土動工。"}]', NULL, NULL, 5, 5274, NULL),
(5275, 'property inspection', '/''prɒpərti ɪnˌspekʃən/', 'noun', '{"zh-TW":["房產檢查；物業驗查"],"en":["a formal examination of a property''s condition, usually conducted before purchase"]}', NULL, 'schedule a property inspection / property inspection report / pass the property inspection', '[{"en":"A thorough property inspection is essential before finalizing any real estate purchase.","zh-TW":"在最終確定任何房地產購買之前，進行徹底的房產檢查是必不可少的。"},{"en":"The property inspection revealed several minor defects that the seller agreed to fix.","zh-TW":"房產檢查發現了幾個賣方同意修復的小缺陷。"}]', NULL, NULL, 5, 5275, NULL),
(5276, 'property ladder', '/''prɒpərti ˌlædər/', 'noun', '{"zh-TW":["置業階梯；房產晉升"],"en":["the series of progressively more expensive properties that a person acquires as they move up in the housing market"]}', NULL, 'climb the property ladder / get on the property ladder / bottom of the property ladder', '[{"en":"Getting on the property ladder is increasingly difficult for young people.","zh-TW":"對年輕人來說，踏上置業階梯越來越困難。"},{"en":"They bought a small apartment as their first step on the property ladder.","zh-TW":"他們購買了一個小公寓，作為踏上置業階梯的第一步。"}]', NULL, NULL, 5, 5276, NULL),
(5277, 'property management', '/ˈprɒpərti ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["物業管理"],"en":["the operation and oversight of real estate on behalf of an owner"]}', NULL, 'provide property management / property management fee', '[{"en":"A professional property management company handles tenant issues.","zh-TW":"專業的物業管理公司處理租戶問題。"},{"en":"Property management includes maintenance, leasing, and rent collection.","zh-TW":"物業管理包括維護、租賃和收租。"}]', '{"noun":"property manager"}', NULL, 5, 5277, NULL),
(5278, 'property management company', '/''prɒpərti ˌmænɪdʒmənt ˌkʌmpəni/', 'noun', '{"zh-TW":["物業管理公司"],"en":["a company hired to oversee the day-to-day operations of rental properties on behalf of owners"]}', NULL, 'hire a property management company / property management company fee', '[{"en":"She hired a property management company to find tenants and handle maintenance.","zh-TW":"她聘請了一家物業管理公司來尋找租戶並處理維護工作。"},{"en":"A reputable property management company can maximize rental income while minimizing vacancies.","zh-TW":"信譽良好的物業管理公司可以最大化租金收入，同時最大限度地減少空置率。"}]', NULL, NULL, 5, 5278, NULL),
(5279, 'property rights', '/ˈprɒpərti raɪts/', 'noun', '{"zh-TW":["財產權；所有權"],"en":["legal rights to possess, use, and dispose of property"]}', NULL, 'protect property rights / enforce property rights', '[{"en":"Strong property rights encourage foreign investment.","zh-TW":"強力的財產權鼓勵外國投資。"},{"en":"The property rights were transferred to the new owner at closing.","zh-TW":"財產權在交割時轉讓給了新業主。"}]', NULL, NULL, 5, 5279, NULL),
(5280, 'property tax', '/ˈprɒpərti tæks/', 'noun', '{"zh-TW":["房產稅；地方稅"],"en":["a tax based on the value of owned property"]}', NULL, 'pay property tax / property tax rate', '[{"en":"Property taxes in this area increased by five percent.","zh-TW":"該地區的房產稅增加了五個百分點。"},{"en":"Property tax revenue funds local schools and services.","zh-TW":"房產稅收入資助當地學校和服務。"}]', NULL, NULL, 4, 5280, NULL),
(5281, 'property valuation', '/''prɒpərti ˌvæljuˈeɪʃən/', 'noun', '{"zh-TW":["房產估值；房屋評估"],"en":["the process of determining the current worth of a property"]}', NULL, 'request a property valuation / accurate property valuation / property valuation report', '[{"en":"A professional property valuation is essential for setting a realistic asking price.","zh-TW":"專業的房產估值對於設定合理的要價至關重要。"},{"en":"Lenders require a property valuation before approving a mortgage application.","zh-TW":"貸款機構在批准按揭申請前需要進行房產估值。"}]', '{"verb":"value"}', NULL, 5, 5281, NULL),
(5282, 'proportion', '/prəˈpɔːrʃən/', 'noun', '{"zh-TW":["比例；部分","比例"],"en":["a part of a whole; ratio","a part considered in relation to the whole"]}', '{"prefix":{"text":"pro-","meaning":"for"},"root":{"text":"portion","meaning":"part (部分)"}}', 'in proportion to / a large proportion / out of proportion; in proportion / a high proportion / out of proportion', '[{"en":"A large proportion of the budget goes to R&D.","zh-TW":"預算的大部分用於研發。"},{"en":"Salary should be in proportion to experience.","zh-TW":"薪資應與經驗成比例。"},{"en":"A high proportion of staff are part-time.","zh-TW":"很高比例的員工是兼職的。"},{"en":"Keep expenses in proportion to revenue.","zh-TW":"使支出與收入成比例。"}]', '{"adjective":"proportional, proportionate","adverb":"proportionally"}', NULL, 4, 5282, NULL),
(5283, 'proportional', '/prəˈpɔːrʃənl/', 'adjective', '{"zh-TW":["按比例的；成比例的"],"en":["corresponding in size or degree to something else"]}', NULL, 'proportional representation / proportional allocation', '[{"en":"Costs are allocated proportionally based on usage.","zh-TW":"成本按使用情況按比例分配。"},{"en":"Dividends are paid proportionally to the number of shares held.","zh-TW":"股息按持有股份數量按比例支付。"}]', '{"adverb":"proportionally","noun":"proportion"}', NULL, 4, 5283, 912),
(5284, 'proportionality', '/prəˌpɔːrʃəˈnælɪti/', 'noun', '{"zh-TW":["相稱性；比例原則"],"en":["the quality of corresponding in size or degree; a legal principle requiring balanced responses"]}', NULL, 'principle of proportionality / proportionality test / strict proportionality', '[{"en":"The court applied the proportionality principle to assess whether the restriction was justified.","zh-TW":"法院適用比例原則評估限制措施是否合理。"},{"en":"Regulatory enforcement should follow the principle of proportionality in applying penalties.","zh-TW":"監管執法在施加處罰時應遵循相稱性原則。"}]', '{"adjective":"proportional","adverb":"proportionally"}', NULL, 5, 5284, NULL),
(5285, 'proposal', '/prəˈpoʊzəl/', 'noun', '{"zh-TW":["提案；建議"],"en":["a formal suggestion or plan"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"pos","meaning":"put (放)"},"suffix":{"text":"-al","meaning":"名詞後綴"}}', 'submit a proposal / business proposal / accept a proposal', '[{"en":"The board approved the merger proposal.","zh-TW":"董事會批准了合併提案。"},{"en":"Please submit your proposal by Friday.","zh-TW":"請於週五前提交提案。"}]', '{"verb":"propose","noun":"proposer"}', NULL, 3, 5285, 187),
(5286, 'propose', '/prəˈpoʊz/', 'verb', '{"zh-TW":["提議；求婚","提議；建議"],"en":["to suggest a plan or idea"]}', '{"prefix":{"text":"pro-","meaning":"forward (向前)"},"root":{"text":"pose","meaning":"put (放置)"},"logic":"把想法放到前面來，即「提議」。"}', 'propose a plan / propose changes / propose a solution; propose a plan / propose changes / propose that', '[{"en":"I propose we postpone the meeting.","zh-TW":"我提議我們延後會議。"},{"en":"She proposed several changes to the plan.","zh-TW":"她對計畫提出了幾項修改建議。"},{"en":"I propose that we postpone the meeting.","zh-TW":"我提議我們推遲會議。"},{"en":"She proposed a new marketing strategy.","zh-TW":"她提出了新的行銷策略。"}]', '{"noun":"proposal"}', NULL, 3, 5286, NULL),
(5287, 'proposition', '/ˌprɒpəˈzɪʃən/', 'noun', '{"zh-TW":["主張；命題"],"en":["a statement that affirms or denies something; a formal proposal"]}', NULL, 'test a proposition / core proposition / value proposition', '[{"en":"The paper tests the proposition that taxes affect investment.","zh-TW":"論文驗證了稅收影響投資的命題。"},{"en":"The business proposition was compelling enough to attract investors.","zh-TW":"這個商業主張足夠有說服力，吸引了投資者。"}]', '{"verb":"propose","adjective":"propositional"}', NULL, 4, 5287, NULL),
(5288, 'proprietary', '/prəˈpraɪətəri/', 'adjective', '{"zh-TW":["專有的；私有的"],"en":["relating to an owner or ownership; manufactured exclusively by one company"]}', NULL, 'proprietary technology / proprietary software / proprietary information', '[{"en":"The company protected its proprietary technology with multiple patents.","zh-TW":"公司用多項專利保護其專有技術。"},{"en":"Sharing proprietary information with a competitor is a serious breach of contract.","zh-TW":"與競爭對手分享專有信息是嚴重違反合同的行為。"}]', NULL, NULL, 4, 5288, NULL),
(5289, 'proprietary information', '/prəˈpraɪɪteri ˌɪnfərˈmeɪʃən/', 'noun', '{"zh-TW":["專有資訊；機密資訊"],"en":["confidential business information owned by a company"]}', NULL, 'protect proprietary information / proprietary information agreement', '[{"en":"Employees must not disclose proprietary information to competitors.","zh-TW":"員工不得向競爭對手披露專有資訊。"},{"en":"The NDA prevents contractors from sharing proprietary information.","zh-TW":"保密協議防止承包商分享專有資訊。"}]', NULL, NULL, 5, 5289, NULL),
(5290, 'proprietary trading', '/prəˈpraɪətəri ˈtreɪdɪŋ/', 'noun', '{"zh-TW":["自營交易"],"en":["trading financial instruments using a firm''s own capital"]}', NULL, 'proprietary trading desk / proprietary trading profit / restrict proprietary trading', '[{"en":"Banks restricted proprietary trading after the financial crisis.","zh-TW":"金融危機後，銀行限制了自營交易。"},{"en":"Proprietary trading can generate significant profits but also large losses.","zh-TW":"自營交易可以產生顯著利潤，但也可能帶來巨大損失。"}]', NULL, NULL, 5, 5290, NULL),
(5291, 'prosecution', '/ˌprɒsɪˈkjuːʃən/', 'noun', '{"zh-TW":["起訴；檢方"],"en":["the process of charging someone with a crime"]}', NULL, 'criminal prosecution / the prosecution rests', '[{"en":"He faces prosecution for fraud.","zh-TW":"他面臨詐欺罪的起訴。"},{"en":"The prosecution presented strong evidence.","zh-TW":"檢方提出了有力的證據。"}]', '{"verb":"prosecute","noun2":"prosecutor"}', NULL, 4, 5291, NULL),
(5292, 'prosody', '/ˈprɒsədi/', 'noun', '{"zh-TW":["韻律學；詩律"],"en":["the patterns of rhythm and sound in poetry"]}', NULL, 'study prosody / prosody of a poem / English prosody', '[{"en":"Understanding prosody helps readers appreciate the musicality of poetry.","zh-TW":"理解韻律學幫助讀者欣賞詩歌的音樂性。"},{"en":"The professor analyzed the prosody of Shakespeare''s sonnets in class.","zh-TW":"教授在課上分析了莎士比亞十四行詩的韻律。"}]', '{"adjective":"prosodic"}', NULL, 3, 5292, NULL),
(5293, 'prospect', '/ˈprɒspɛkt/', 'noun', '{"zh-TW":["前景；可能性","潛在客戶","前景；展望"],"en":["the possibility of future success","a potential customer"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"spect","meaning":"look (看)"}}', 'job prospects / future prospects / prospective client; career prospects / bright prospects / prospective buyer', '[{"en":"Job prospects in tech are excellent.","zh-TW":"科技業的就業前景很好。"},{"en":"We have several prospective clients.","zh-TW":"我們有幾個潛在客戶。"},{"en":"Career prospects in this field are bright.","zh-TW":"這個領域的職業前景光明。"},{"en":"We have several prospective buyers.","zh-TW":"我們有幾個潛在買家。"}]', '{"adjective":"prospective","verb":"prospect"}', NULL, 3, 5293, 426),
(5294, 'prospectus', '/prəˈspɛktəs/', 'noun', '{"zh-TW":["公開說明書；招股書"],"en":["a printed document describing a company''s offering"]}', NULL, 'investment prospectus / issue a prospectus', '[{"en":"Read the prospectus before investing.","zh-TW":"投資前請閱讀公開說明書。"},{"en":"The company issued a prospectus for the IPO.","zh-TW":"公司為IPO發行了招股書。"}]', '{"noun":"prospectus"}', NULL, 4, 5294, NULL),
(5295, 'prosperity', '/prɒˈspɛrɪti/', 'noun', '{"zh-TW":["繁榮；興旺"],"en":["the state of being successful"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"sper","meaning":"hope (希望)"},"suffix":{"text":"-ity","meaning":"狀態"}}', 'economic prosperity / bring prosperity', '[{"en":"The policy brought prosperity to the region.","zh-TW":"政策為該地區帶來繁榮。"},{"en":"Economic prosperity depends on stable policies.","zh-TW":"經濟繁榮取決於穩定政策。"}]', '{"adjective":"prosperous","verb":"prosper"}', NULL, 4, 5295, NULL),
(5296, 'protect', '/prəˈtɛkt/', 'verb', '{"zh-TW":["保護"],"en":["to keep safe from harm"]}', '{"prefix":{"text":"pro-","meaning":"in front of"},"root":{"text":"tect","meaning":"cover (覆蓋)"}}', 'protect against / protect the environment / protect rights', '[{"en":"Laws exist to protect consumers.","zh-TW":"法律的存在是為了保護消費者。"},{"en":"We must protect our intellectual property.","zh-TW":"我們必須保護智慧財產權。"}]', '{"noun":"protection, protector","adjective":"protective"}', NULL, 3, 5296, NULL),
(5297, 'protectionism', '/prəˈtekʃənɪzəm/', 'noun', '{"zh-TW":["保護主義"],"en":["government policies protecting domestic industries from foreign competition"]}', NULL, 'rise of protectionism / protectionism measures / trade protectionism', '[{"en":"Rising protectionism threatens the global trading system.","zh-TW":"保護主義的興起威脅著全球貿易體系。"},{"en":"Import tariffs are a common form of protectionism.","zh-TW":"進口關稅是保護主義的常見形式。"}]', '{"adjective":"protectionist","verb":"protect"}', NULL, 5, 5297, NULL),
(5298, 'protective gear', '/''prəˌtektɪv ˌɡɪər/', 'noun', '{"zh-TW":["防護裝備；保護裝備"],"en":["equipment worn to protect the body during sports or physical activity"]}', NULL, 'wear protective gear / required protective gear / sports protective gear', '[{"en":"Cyclists must wear protective gear including helmets and pads.","zh-TW":"自行車手必須佩戴包括頭盔和護墊在內的防護裝備。"},{"en":"Protective gear significantly reduces the risk of serious injury in contact sports.","zh-TW":"防護裝備顯著降低了接觸性運動中嚴重受傷的風險。"}]', NULL, NULL, 5, 5298, NULL),
(5299, 'protein', '/''prəʊtiːn/', 'noun', '{"zh-TW":["蛋白質"],"en":["a class of essential nutrients composed of amino acids, vital for body growth and repair"]}', NULL, 'protein intake / lean protein / protein-rich', '[{"en":"Chicken, fish, and beans are excellent sources of protein.","zh-TW":"雞肉、魚類和豆類是優質蛋白質的絕佳來源。"},{"en":"Athletes often increase their protein intake after intense workouts.","zh-TW":"運動員在高強度訓練後通常會增加蛋白質攝取量。"}]', '{"adjective":"protein-rich"}', NULL, 3, 5299, NULL);